versions.css:
*{box-sizing:border-box}
body{margin:0;min-height:100svh;display:grid;place-items:center;background:#090c12;color:#eef4ff;font-family:Inter,"Segoe UI","Microsoft YaHei",sans-serif;background-image:radial-gradient(ellipse at 50% 45%,#1c294444,transparent 65%)}
main{width:100%;padding:40px 24px;display:grid;justify-items:center;gap:36px}
header{text-align:center}h1{font-size:24px;font-weight:500;letter-spacing:4px;margin:0 0 12px}header p{font-size:12px;color:#8a98af;letter-spacing:2px;margin:0}
.stage{width:min(330px,100%);aspect-ratio: .72;perspective:900px;touch-action:none;outline:none;cursor:grab}
.stage:active{cursor:grabbing}.stage:focus-visible{outline:2px solid #b9d8ff;outline-offset:14px;border-radius:26px}
.card{--px:50%;--py:50%;--light:0;position:relative;width:100%;height:100%;border-radius:26px;transform-style:preserve-3d;background:linear-gradient(140deg,#253651,#101827 48%,#302c43);border:1px solid #b7d0f54d;box-shadow:0 30px 65px #0008,inset 0 1px 0 #fff3;will-change:transform;pointer-events:none}
.surface{position:absolute;inset:0;border-radius:inherit;overflow:hidden;background:repeating-linear-gradient(115deg,transparent 0 3px,#ffffff02 3px 4px)}
.surface:before{content:"";position:absolute;inset:-35%;background:conic-gradient(from 20deg at var(--px) var(--py),#7ce9ff00,#7ce9ff33,#c3b0ff44,#ffc6dd22,#efffc933,#7ce9ff00);mix-blend-mode:screen;opacity:calc(.28 + var(--light)*.6)}
.surface:after{content:"";position:absolute;inset:0;background:radial-gradient(circle at var(--px) var(--py),#fff9 0%,#d6edff33 15%,#9bbcff0d 35%,transparent 65%);mix-blend-mode:screen;opacity:var(--light)}
.content{position:absolute;inset:28px;display:flex;flex-direction:column;justify-content:space-between;transform:translateZ(32px)}
.top,.bottom{display:flex;justify-content:space-between;align-items:center}.brand{font-size:11px;letter-spacing:3px}.edition{font-size:9px;color:#c3cddd;letter-spacing:1px}.mark{font-size:20px;color:#cfdef7}
.art{position:absolute;inset:24% 17% 28%;transform:translateZ(45px);display:grid;place-items:center}
.ring{position:absolute;width:100%;aspect-ratio:1;border:1px solid #dcecff88;border-radius:50%;box-shadow:inset 5px 0 14px #8ad9ff22,3px 0 12px #bfa8ff22;transform:rotate(-35deg) scaleX(.53)}
.ring:nth-child(2){transform:rotate(25deg) scaleX(.53)}.ring:nth-child(3){transform:rotate(85deg) scaleX(.53)}
.core{width:56px;height:56px;border-radius:50%;background:radial-gradient(circle at 30% 25%,#fff,#c9e7fa 18%,#8ba9d0 42%,#3e456b 70%,#171f36);box-shadow:0 0 38px #aecfff44}
.name{margin-top:auto;margin-bottom:30px}.name h2{font-family:Georgia,serif;font-size:clamp(32px,8vw,43px);font-weight:400;letter-spacing:-1px;margin:0 0 8px}.name p{font-size:10px;letter-spacing:3px;color:#a9b8d0;margin:0}
.bottom{border-top:1px solid #ffffff20;padding-top:18px;font-size:9px;letter-spacing:2px;color:#acbdd4}.bottom b{font-size:16px;font-weight:400;color:#d6e5ff}
.hint{text-align:center;font-size:12px;color:#a1aec2;line-height:1.9;margin:0}.hint span{display:block;font-size:10px;color:#58667c;letter-spacing:1px}
@media(max-height:650px){main{gap:20px;padding:24px}.stage{width:min(260px,75vw)}header h1{font-size:20px}.content{inset:22px}.name{margin-bottom:18px}}
@media(prefers-reduced-motion:reduce){.card{will-change:auto}}

