const stage = document.querySelector('.stage');
const card = document.querySelector('.card');
const reduced = matchMedia('(prefers-reduced-motion: reduce)');
const state = {x:0,y:0,vx:0,vy:0,tx:0,ty:0,light:0,targetLight:0};
let frame = 0, previous = 0, activePointer = null;
function paint(){
 card.style.transform = 'rotateX('+state.x+'deg) rotateY('+state.y+'deg)';
 card.style.setProperty('--light',state.light.toFixed(4));
}
function animate(time){
 const dt = Math.min((time-previous)/1000 || 1/60,1/30); previous=time;
 // Substeps keep the damped spring stable across different refresh rates.
 const steps=4, h=dt/steps;
 for(let i=0;i<steps;i++){
  state.vx+=((state.tx-state.x)*210-state.vx*19)*h;
  state.vy+=((state.ty-state.y)*210-state.vy*19)*h;
  state.x+=state.vx*h; state.y+=state.vy*h;
 }
 state.light+=(state.targetLight-state.light)*(1-Math.exp(-12*dt));
 if(reduced.matches){state.x=state.y=state.vx=state.vy=0;state.light=state.targetLight;}
 const settled=Math.abs(state.x-state.tx)+Math.abs(state.y-state.ty)+Math.abs(state.vx)+Math.abs(state.vy)<.015 && Math.abs(state.light-state.targetLight)<.001;
 if(settled || reduced.matches){state.x=reduced.matches?0:state.tx;state.y=reduced.matches?0:state.ty;state.vx=state.vy=0;state.light=state.targetLight;frame=0;paint();return;}
 paint();frame=requestAnimationFrame(animate);
}
function wake(){if(!frame){previous=performance.now();frame=requestAnimationFrame(animate);}}
function follow(event){
 if(activePointer!==null && event.pointerId!==activePointer)return;
 if(event.pointerType!=='mouse' && activePointer===null)return;
 // Measure the stationary hit area, never the transformed card.
 const bounds=stage.getBoundingClientRect();
 const x=Math.max(0,Math.min(1,(event.clientX-bounds.left)/bounds.width));
 const y=Math.max(0,Math.min(1,(event.clientY-bounds.top)/bounds.height));
 state.tx=(.5-y)*24;state.ty=(x-.5)*28;state.targetLight=1;
 card.style.setProperty('--px',x*100+'%');card.style.setProperty('--py',y*100+'%');wake();
}
function reset(){state.tx=state.ty=state.targetLight=0;wake();}
function release(event){
 if(activePointer!==null && event && event.pointerId!==activePointer)return;
 const id=activePointer;activePointer=null;
 if(id!==null && stage.hasPointerCapture(id))stage.releasePointerCapture(id);
 reset();
}
stage.addEventListener('pointerdown',event=>{
 if(activePointer!==null || !event.isPrimary || event.button!==0)return;
 activePointer=event.pointerId;stage.setPointerCapture(event.pointerId);follow(event);
});
stage.addEventListener('pointermove',follow);
stage.addEventListener('pointerleave',()=>{if(activePointer===null)reset();});
stage.addEventListener('pointerup',release);
stage.addEventListener('pointercancel',release);
stage.addEventListener('lostpointercapture',()=>{activePointer=null;reset();});
window.addEventListener('blur',()=>release());
stage.addEventListener('blur',()=>release());
stage.addEventListener('keydown',event=>{
 const directions={ArrowUp:[10,0],ArrowDown:[-10,0],ArrowLeft:[0,-12],ArrowRight:[0,12]};
 if(!directions[event.key])return;event.preventDefault();
 [state.tx,state.ty]=directions[event.key];state.targetLight=1;
 card.style.setProperty('--px',50+state.ty*3+'%');card.style.setProperty('--py',50-state.tx*3+'%');wake();
});
stage.addEventListener('keyup',event=>{if(event.key.startsWith('Arrow'))reset();});
document.addEventListener('visibilitychange',()=>{if(document.hidden)release();});
reduced.addEventListener('change',()=>reset());
